// ============================================================
// WF3 - Node Code: filter baris yang layak diarsipkan.
// Syarat SEMUA harus terpenuhi:
//   1. Status_Terakhir === "Delivered".
//   2. Waktu entri Delivered terakhir di riwayat (fallback: Timestamp_Update)
//      lebih tua dari 30 hari dari sekarang.
// Baris dengan JSON korup ATAU status non-Delivered TIDAK diarsipkan.
// ============================================================

const rows = $input.all().map(i => i.json);

const now = Date.now();
const AMBANG_MS = 30 * 24 * 60 * 60 * 1000; // 30 hari.

// Tanggal diarsipkan (ISO +07:00 Asia/Jakarta).
function nowJakartaISO() {
  const d = new Date(Date.now() + 7 * 60 * 60 * 1000);
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())}` +
         `T${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}+07:00`;
}
const tanggalArsip = nowJakartaISO();

const lolos = [];

for (const row of rows) {
  const status = String(row.Status_Terakhir || '').trim();

  // Syarat 1: harus Delivered.
  if (status !== 'Delivered') continue;

  // Parse riwayat dengan aman. JSON korup => LEWATI (tidak diarsipkan).
  let riwayat = null;
  const raw = row.Riwayat_Posisi_JSON;
  if (raw !== undefined && raw !== null && String(raw).trim() !== '') {
    try {
      const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
      if (!Array.isArray(parsed)) throw new Error('bukan array');
      riwayat = parsed;
    } catch (e) {
      // Korup => jangan arsip demi keamanan.
      continue;
    }
  }

  // Tentukan waktu Delivered terakhir dari riwayat.
  let waktuDelivered = null;
  if (riwayat && riwayat.length) {
    for (const ev of riwayat) {
      if (ev && String(ev.status).trim() === 'Delivered' && ev.waktu) {
        const t = Date.parse(ev.waktu);
        if (!isNaN(t)) {
          if (waktuDelivered === null || t > waktuDelivered) waktuDelivered = t;
        }
      }
    }
  }

  // Fallback ke Timestamp_Update jika tidak ada entri Delivered valid di riwayat.
  if (waktuDelivered === null) {
    const t = Date.parse(row.Timestamp_Update);
    if (!isNaN(t)) waktuDelivered = t;
  }

  // Tanpa waktu acuan valid => jangan arsip.
  if (waktuDelivered === null) continue;

  // Syarat 2: lebih tua dari 30 hari.
  if ((now - waktuDelivered) <= AMBANG_MS) continue;

  // Lolos semua syarat. Siapkan payload arsip (kolom sama + Tanggal_Diarsipkan).
  lolos.push({
    json: {
      No_Resi: row.No_Resi || '',
      Pengirim: row.Pengirim || '',
      Penerima: row.Penerima || '',
      Status_Terakhir: row.Status_Terakhir || '',
      Riwayat_Posisi_JSON: (typeof raw === 'string') ? raw : JSON.stringify(riwayat || []),
      Timestamp_Update: row.Timestamp_Update || '',
      Tanggal_Diarsipkan: tanggalArsip,
      // Simpan row_number untuk keperluan delete dari sheet Utama nanti.
      _row_number: row.row_number
    }
  });
}

// Jika tidak ada yang lolos, kembalikan array kosong => workflow selesai
// tanpa aksi pada cabang berikutnya.
return lolos;

// ============================================================
// WF3 - Node Code: siapkan daftar row_number untuk dihapus dari sheet Utama.
// Dijalankan SETELAH append ke Archive sukses (urutan aman).
// Delete harus dari row number TERBESAR ke terkecil agar index tidak bergeser.
// ============================================================

// Ambil data hasil filter (yang sudah diarsipkan) dari node Filter.
const items = $items('Code Filter Kandidat Arsip');

// Kumpulkan row_number valid.
const rowNumbers = [];
for (const it of items) {
  const rn = it.json._row_number;
  if (rn !== undefined && rn !== null && !isNaN(Number(rn))) {
    rowNumbers.push(Number(rn));
  }
}

// Urutkan MENURUN (terbesar dulu) agar penghapusan tidak menggeser index.
rowNumbers.sort((a, b) => b - a);

// Keluarkan satu item per row_number agar node Delete berikutnya
// mengeksekusi berurutan.
return rowNumbers.map(rn => ({ json: { row_number: rn } }));
